require(['jquery'], function ($) {
  $(document).on('xwiki:html5upload:done', function (e) {
    if ($(e.target).prop('id') == 'confluenceUploadFile') {
      $('#confluencePackages').data('liveData').updateEntries();
    }
  });

  $('#confluence-pro-tab-root li').on('click', function () {
    let currentElement = $(this);
    let selectedElement = $('#confluence-pro-tab-root .active');
    selectedElement.removeClass('active');
    currentElement.addClass('active');
  })
})

.cfmPrerequisites ul{
  list-style: none;
}

.cfmTitleSummary {
  font-size:1.7rem;
  line-height:1.3rem;
  margin:0 0 1rem 0;
}

.cfmTitleSummary, summary.cfmTitle {
  display:list-item;
}

.cfmTitleSummary::after {
  font-style: italic;
  color: #bbb;
  margin-left: 0.5em;
}

.cfmTitleSummary.completed::after {
  content: "(${services.localization.render('confluencepro.prerequisites.completed')})"
}

.cfmTitleSummary.incomplete::after {
  content: "(${services.localization.render('confluencepro.prerequisites.incomplete')})"
}

#confluencePackages .attachmentActions a:nth-last-child(2)
{
  margin: 5px;
}

## We add a margin only to the icon on the right
#confluencePackages .attachmentActions a > span:nth-child(1)
{
  margin-right: 3px;
}


.howToMigrateSubsection {
  margin : 20px;
}

.howToMigrateSubsection {
  color: @text-color;
}

.cmpServerParametersForm label, #confluence-pro-tab-root label {
  font-weight: normal;
}

#confluencePackages .attachmentActions a:nth-last-child(2) {
  margin: 5px;
}

## We add a margin only to the icon on the right
#confluencePackages .attachmentActions a > span:nth-child(1) {
  margin-right: 3px;
}

.cmpServerParametersForm label {
  font-weight: normal;
}

.confluence-pro-tab-container-new-migration > p {
  display: none !important;
}

.cfmTitleSection {
  font-weight: bold;
}

#cfmHowToMigrateUploadCollapse,
#cfmHowToMigrateServerCollapse,
#cfmHowToMigrateBatchesCollapse {
  margin-top: 1em;
}

#confluencePackages .action.collaboraEdit {
  display: none !important
}
